  paths[p].tmax = FLT_MAX;
  paths[p].selfPrim = NONE;
  paths[p].T = vec3<f32>(1.0);
  paths[p].misRayPdf = 0.0;
  paths[p].minRayPdf = FLT_MAX;
  paths[p].misN = vec3<f32>(0.0);
  paths[p].contProb = 1.0;
